insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-547','5-28',547,'可靠','kě kào','đáng tin cậy','这是一家可靠的公司。','Zhè shì yījiā kěkào de gōngsī.','Đây là một công ty đáng tin cậy.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-548','5-28',548,'可怕','kě pà','đáng sợ','这个情况可能会变得很可怕。','Zhège qíngkuàng kěnéng huì biàn dé hěn kěpà.','Tình hình này có thể trở nên rất đáng sợ.');
