insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-552','5-28',552,'客观','kè guān','khách quan','我们需要一个客观的评估。','Wǒmen xūyào yīgè kèguān de pínggū.','Chúng ta cần một đánh giá khách quan.');
