insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-554','5-28',554,'空间','kōng jiān','không gian','这间房间的空间很大。','Zhè jiān fángjiān de kōngjiān hěn dà.','Không gian của căn phòng này rất rộng.');
