insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-915','5-46',915,'淘气','táo qì','tinh nghịch','孩子们有点淘气。','Háizimen yǒudiǎn táoqì.','Bọn trẻ hơi nghịch ngợm.');
