insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-918','5-46',918,'特色','tè sè','đặc sắc, đặc điểm đặc sắc','这个产品有独特的特色。','Zhège chǎnpǐn yǒu dútè de tèsè.','Sản phẩm này có những đặc điểm độc đáo.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-919','5-46',919,'特殊','tè shū','đặc biệt, đặc thù (quan hệ, nghi lễ, yêu cầu, đãi ngộ)','他对这个项目有特殊的理解。','Tā duì zhège xiàngmù yǒu tèshū de lǐjiě.','Anh ấy có sự hiểu biết đặc biệt về dự án này.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-920','5-46',920,'特征','tè zhēng','đặc trưng','每个人都有自己的特征。','Měi gè rén dōu yǒu zìjǐ de tèzhēng.','Mỗi người đều có những đặc điểm riêng của mình.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-921','5-47',921,'疼爱','téng ài','chiều chuộng, yêu chiều','父母对孩子的疼爱是无条件的。','Fùmǔ duì háizi de téng''ài shì wú tiáojiàn de.','Tình yêu của cha mẹ dành cho con cái là vô điều kiện.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-922','5-47',922,'提倡','tí chàng','đề xướng','他提倡环保活动。','Tā tícàng huánbǎo huódòng.','Anh ấy cổ vũ các hoạt động bảo vệ môi trường.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-923','5-47',923,'提纲','tí gāng','đề cương','这篇文章的提纲很详细。','Zhè piān wénzhāng de tígāng hěn xiángxì.','Đề cương của bài viết này rất chi tiết.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-924','5-47',924,'提问','tí wèn','hỏi','他在提问时表现得很认真。','Tā zài tíwèn shí biǎoxiàn de hěn rènzhēn.','Anh ấy thể hiện sự nghiêm túc khi đặt câu hỏi.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-925','5-47',925,'题目','tí mù','đề mục','这个题目很有挑战性。','Zhège tímù hěn yǒu tiǎozhàn xìng.','Đề tài này rất có tính thách thức.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-926','5-47',926,'体会','tǐ huì','cảm nhận','他从这次旅行中体会到了很多东西。','Tā cóng zhè cì lǚxíng zhōng tǐhuì dàole hěn duō dōngxī.','Anh ấy đã cảm nhận được nhiều điều từ chuyến đi này.');
