insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-928','5-47',928,'体现','tǐ xiàn','thể hiện','他的工作体现了高水平的专业性。','Tā de gōngzuò tǐxiànle gāo shuǐpíng de zhuānyè xìng.','Công việc của anh ấy thể hiện mức độ chuyên môn cao.');
