insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-930','5-47',930,'天空','tiān kōng','bầu trời','他们在天空中看到了彩虹。','Tāmen zài tiānkōng zhōng kàn dàole cǎihóng.','Họ đã thấy cầu vồng trên bầu trời.');
insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-931','5-47',931,'天真','tiān zhēn','hồn nhiên','她的天真让人感到温暖。','Tā de tiānzhēn ràng rén gǎndào wēnnuǎn.','Sự ngây thơ của cô ấy làm cho người ta cảm thấy ấm áp.');
