insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-934','5-47',934,'挑战','tiǎo zhàn','thách thức, thử thách, thách','他们接受了一个巨大的挑战。','Tāmen jiēshòule yīgè jùdà de tiǎozhàn.','Họ đã chấp nhận một thách thức lớn.');
