insert into vocabulary(id,lesson_id,position,hanzi,pinyin,meaning_vi,example_zh,example_pinyin,example_vi) values('5-938','5-47',938,'痛快','tòng kuài','sung sướng','这次经历让他感到痛快。','Zhè cì jīnglì ràng tā gǎndào tòngkuài.','Kinh nghiệm này làm anh ấy cảm thấy rất thỏa mãn.');
